window.STUDIA_CARDS=[{"id": "metodologia/wyklad-3-fiszki:e37b26db", "q": "Po co opisuje się dane przed testowaniem hipotez?", "a": "<p>Żeby <strong>zapoznać się z danymi</strong>, sprawdzić <strong>równoliczność grup</strong>, wyłapać <strong>dewiantów</strong> (wyniki silnie odstające) i <strong>błędy wpisywania</strong>, zaplanować dalsze analizy i zaprezentować wyniki. Wstępny ogląd może też ujawnić błędy, które uniemożliwiają zaplanowane analizy.</p>", "src": "Po co opisywać dane", "k": ["zapoznanie się z danymi", "równoliczność grup", "dewianci i błędy wpisywania", "planowanie analiz"], "u": "wyklad-3.html", "s": "s1"}, {"id": "metodologia/wyklad-3-fiszki:e227ad17", "q": "Czy statystyki opisowe pozwalają wnioskować o populacji?", "a": "<p><strong>Nie.</strong> Służą do opisu danych w próbie. Mimo to nigdy nie zaczyna się analizy bez nich, bo chronią przed wieloma błędami.</p>", "src": "Po co opisywać dane", "k": ["nie", "opis danych w próbie", "chronią przed błędami"], "u": "wyklad-3.html", "s": "s1"}, {"id": "metodologia/wyklad-3-fiszki:436c56af", "q": "Na jakie trzy grupy dzieli się statystyki opisowe?", "a": "<p>Miary <strong>tendencji centralnej</strong> (gdzie jest środek), miary <strong>rozproszenia</strong> (jak wyniki rozkładają się wokół środka) i miary <strong>kształtu rozkładu</strong> (skośność i kurtoza).</p>", "src": "Po co opisywać dane", "k": ["tendencja centralna", "rozproszenie", "kształt rozkładu (skośność, kurtoza)"], "u": "wyklad-3.html", "s": "s1"}, {"id": "metodologia/wyklad-3-fiszki:31275391", "q": "Czym różni się „procent” od „procentu ważnych” w tabeli częstości?", "a": "<p><strong>Procent</strong> liczy się z całej próby <strong>razem z brakami danych</strong>, a <strong>procent ważnych</strong> bez braków. Przy 90 osobach i 3 brakach 27 osób to 30% albo 31% (z 87).</p>", "src": "Tabele częstości", "k": ["procent: z całej próby z brakami", "procent ważnych: bez braków"], "u": "wyklad-3.html", "s": "s2"}, {"id": "metodologia/wyklad-3-fiszki:fd1760a4", "q": "Dla jakich zmiennych procent skumulowany ma sens?", "a": "<p>Dla zmiennych co najmniej <strong>porządkowych</strong>, których kategorie da się sensownie uporządkować (np. wykształcenie). Dla zmiennej <strong>nominalnej</strong> (np. zwierzę) SPSS też go liczy, ale jest bezużyteczny.</p>", "src": "Tabele częstości", "k": ["co najmniej porządkowe", "dla nominalnej bezużyteczny"], "u": "wyklad-3.html", "s": "s2"}, {"id": "metodologia/wyklad-3-fiszki:e13cf6d8", "q": "Do czego służy funkcja „Podziel na podzbiory” i o czym trzeba pamiętać?", "a": "<p>Sprawia, że kolejne operacje wykonują się <strong>osobno dla każdej kategorii</strong> wybranej zmiennej (np. grupy wiekowej). Działa w tle, więc trzeba ją <strong>wyłączyć</strong>, gdy nie jest już potrzebna.</p>", "src": "Tabele częstości", "k": ["operacje osobno dla każdej kategorii", "działa w tle", "trzeba ją wyłączyć"], "u": "wyklad-3.html", "s": "s2"}, {"id": "metodologia/wyklad-3-fiszki:e66f4867", "q": "Jaka jest kluczowa reguła sporządzania wykresów?", "a": "<p>Celem wykresu jest <strong>klarowna i jak najprostsza</strong> prezentacja danych. Lepiej oprzeć się pokusie wykresu imponującego graficznie, ale mało czytelnego.</p>", "src": "Wykresy", "k": ["klarowna, prosta prezentacja", "nie efektowność kosztem czytelności"], "u": "wyklad-3.html", "s": "s3"}, {"id": "metodologia/wyklad-3-fiszki:694113cb", "q": "Czym różni się wykres słupkowy od kołowego, jeśli chodzi o braki danych?", "a": "<p>Wykres <strong>słupkowy nie pokazuje</strong> braków danych, a <strong>kołowy pokazuje</strong>. Kołowy staje się nieczytelny przy bardzo wielu kategoriach.</p>", "src": "Wykresy", "k": ["słupkowy nie pokazuje braków", "kołowy pokazuje braki", "kołowy nieczytelny przy wielu kategoriach"], "u": "wyklad-3.html", "s": "s3"}, {"id": "metodologia/wyklad-3-fiszki:d41cdb46", "q": "Co przedstawia pojedynczy słupek histogramu?", "a": "<p><strong>Przedział klasowy</strong>: grupę wyników o równej rozpiętości, nie pojedynczy wynik. Dzięki temu histogram nadaje się do zmiennych <strong>ilościowych</strong> o wielu wartościach.</p>", "src": "Wykresy", "k": ["przedział klasowy", "grupa wyników o równej rozpiętości"], "u": "wyklad-3.html", "s": "s3"}, {"id": "metodologia/wyklad-3-fiszki:513e06c1", "q": "Czym różni się rozkład w próbie od rozkładu z próby?", "a": "<p><strong>W próbie</strong>: empiryczny rozkład wyników jednego badania, jedyny, którego właściwości można określić. <strong>Z próby</strong> (próbkowania): <strong>teoretyczny</strong> rozkład statystyki (np. średniej) z wielu hipotetycznych prób; pozwala określić precyzję i jest podstawą wnioskowania.</p>", "src": "Rozkład: w populacji, w próbie, z próby", "k": ["w próbie: empiryczny rozkład wyników", "z próby: teoretyczny rozkład statystyki", "podstawa wnioskowania"], "u": "wyklad-3.html", "s": "s4"}, {"id": "metodologia/wyklad-3-fiszki:de805c47", "q": "Czy zasada minimum 30 obserwacji jest sztywna?", "a": "<p><strong>Nie.</strong> Zależy od metody i od rozrzutu zmiennej w populacji: przy małym rozrzucie wystarczy nawet n = 15, przy dużym nawet 30 może być za mało. Powyżej około 30 błąd maleje już coraz wolniej.</p>", "src": "Rozkład: w populacji, w próbie, z próby", "k": ["nie", "zależy od metody i rozrzutu w populacji", "powyżej ~30 błąd maleje wolniej"], "u": "wyklad-3.html", "s": "s4"}, {"id": "metodologia/wyklad-3-fiszki:3811a11d", "q": "Czym różnią się klasyczne i pozycyjne miary tendencji centralnej?", "a": "<p><strong>Klasyczne</strong> (średnia arytmetyczna, ważona, geometryczna, harmoniczna) opierają się na wszystkich wynikach, więc są <strong>wrażliwe na obserwacje odstające</strong>. <strong>Pozycyjne</strong> (kwantyle, mediana, dominanta) wyznaczają tylko niektóre obserwacje, więc są na nie <strong>odporne</strong>.</p>", "src": "Miary tendencji centralnej", "k": ["klasyczne: wszystkie wyniki", "klasyczne wrażliwe na outliery", "pozycyjne: odporne na outliery"], "u": "wyklad-3.html", "s": "s5"}, {"id": "metodologia/wyklad-3-fiszki:fea12417", "q": "Czym jest modalna i na jakiej skali można ją liczyć?", "a": "<p>To <strong>wartość najczęściej występująca</strong> (w SPSS: dominanta). Można ją liczyć na <strong>każdej skali</strong>. Może jej nie być albo może być kilka (zmienna dwumodalna); jeśli istnieje, jest zawsze wartością obserwowaną.</p>", "src": "Miary tendencji centralnej", "k": ["wartość najczęstsza", "każda skala", "może jej nie być lub być kilka"], "u": "wyklad-3.html", "s": "s5"}, {"id": "metodologia/wyklad-3-fiszki:fccc69e9", "q": "Dlaczego modalną lepiej odczytać z tabeli częstości niż z wyniku SPSS?", "a": "<p>SPSS podaje <strong>zawsze jedną</strong> modalną, nawet gdy jest ich więcej.</p>", "src": "Miary tendencji centralnej", "k": ["SPSS podaje zawsze jedną modalną"], "u": "wyklad-3.html", "s": "s5"}, {"id": "metodologia/wyklad-3-fiszki:c9d8effc", "q": "Jak wyznacza się medianę przy parzystej liczbie obserwacji?", "a": "<p>Jako <strong>średnią z dwóch wartości środkowych</strong> uporządkowanego zbioru. Dla 3 3 3 4 5 6 6 6 mediana wynosi 4,5, czyli wartość, której nie ma w zbiorze.</p>", "src": "Miary tendencji centralnej", "k": ["średnia z dwóch środkowych wartości", "może jej nie być w zbiorze"], "u": "wyklad-3.html", "s": "s5"}, {"id": "metodologia/wyklad-3-fiszki:9a2ee625", "q": "Dla jakiej skali nie można liczyć mediany?", "a": "<p>Dla <strong>nominalnej</strong>, nawet jeśli kategoriom przypisano rosnące liczby (1 Polacy, 2 Niemcy, 3 Francuzi), bo kategorii nie da się uszeregować.</p>", "src": "Miary tendencji centralnej", "k": ["nominalna", "kategorii nie da się uszeregować"], "u": "wyklad-3.html", "s": "s5"}, {"id": "metodologia/wyklad-3-fiszki:ca15d14e", "q": "Na ile części dzielą zbiór tercyle, kwartyle, kwintyle, decyle i percentyle?", "a": "<p>Tercyle na <strong>3</strong>, kwartyle na <strong>4</strong>, kwintyle na <strong>5</strong>, decyle na <strong>10</strong>, percentyle na <strong>100</strong>. Mediana to drugi kwartyl (Q<sub>2</sub>).</p>", "src": "Miary tendencji centralnej", "k": ["tercyle 3, kwartyle 4", "kwintyle 5, decyle 10", "percentyle 100", "mediana = Q2"], "u": "wyklad-3.html", "s": "s5"}, {"id": "metodologia/wyklad-3-fiszki:11585472", "q": "Co pokazuje przykład ocen Jasia i Stasia?", "a": "<p>Obaj mają te same <strong>Mo = 3, Me = 4, M = 3,81</strong>, choć oceny Jasia są bardziej zróżnicowane (rozstęp 4 wobec 2, SD 1,17 wobec 0,87). Same miary tendencji centralnej gubią informację, więc trzeba też liczyć <strong>miary rozproszenia</strong>.</p>", "src": "Miary tendencji centralnej", "k": ["te same miary tendencji centralnej", "różne zróżnicowanie", "potrzebne miary rozproszenia"], "u": "wyklad-3.html", "s": "s5"}, {"id": "metodologia/wyklad-3-fiszki:917d738f", "q": "Jak brzmi relacja Pearsona i kiedy ją stosować?", "a": "<p><strong>3Me = D + 2M</strong>. Tylko dla rozkładów <strong>symetrycznych</strong> lub o niewielkiej asymetrii.</p>", "src": "Miary tendencji centralnej", "k": ["3Me = D + 2M", "rozkłady symetryczne lub lekko asymetryczne"], "u": "wyklad-3.html", "s": "s5"}, {"id": "metodologia/wyklad-3-fiszki:2c6b5703", "q": "Co oznaczają elementy wykresu skrzynkowego?", "a": "<p>Gruba linia to <strong>mediana</strong>; krawędzie skrzynki to <strong>Q<sub>1</sub> i Q<sub>3</sub></strong> (50% wyników w środku); wąsy sięgają do <strong>1,5 rozstępu ćwiartkowego</strong>; <strong>kółka</strong> to obserwacje odstające (1,5–3 IQR od skrzynki), <strong>gwiazdki</strong> to skrajne (ponad 3 IQR).</p>", "src": "Obserwacje odstające", "k": ["linia: mediana", "skrzynka: Q1–Q3", "wąsy: 1,5 IQR", "kółka odstające, gwiazdki skrajne"], "u": "wyklad-3.html", "s": "s6"}, {"id": "metodologia/wyklad-3-fiszki:472a6923", "q": "Kiedy wolno usunąć obserwację odstającą?", "a": "<p>Gdy jest się pewnym, że wartość jest nienaturalna lub wynika z <strong>błędu</strong> (pomiaru, przepisywania). <strong>Nigdy</strong> po to, by uzyskać wynik istotny statystycznie, bo to oszustwo.</p>", "src": "Obserwacje odstające", "k": ["wartość nienaturalna lub błąd", "nigdy dla istotności (oszustwo)"], "u": "wyklad-3.html", "s": "s6"}, {"id": "metodologia/wyklad-3-fiszki:c757a145", "q": "Czym różni się winsoryzacja od trymowania?", "a": "<p><strong>Winsoryzacja</strong> zastępuje skrajne wartości <strong>najbliższymi wartościami</strong> i zachowuje liczebność próby. <strong>Trymowanie</strong> skrajne wartości <strong>obcina</strong> i liczy statystykę na mniejszym zbiorze.</p>", "src": "Obserwacje odstające", "k": ["winsoryzacja: zastępuje najbliższymi wartościami", "zachowuje liczebność", "trymowanie: obcina"], "u": "wyklad-3.html", "s": "s6"}, {"id": "metodologia/wyklad-3-fiszki:76f33195", "q": "Dlaczego zastępowanie wielu outlierów średnią jest złym pomysłem?", "a": "<p>Bo <strong>zaniża miary rozproszenia</strong>, a przez to zawyża statystyki testowe niektórych testów. Sprawdza się tylko przy niewielu obserwacjach odstających.</p>", "src": "Obserwacje odstające", "k": ["zaniża rozproszenie", "zawyża statystyki testowe"], "u": "wyklad-3.html", "s": "s6"}, {"id": "metodologia/wyklad-3-fiszki:b096abf9", "q": "Jaką miarę rozproszenia podać przy średniej, a jaką przy medianie?", "a": "<p>Przy <strong>średniej</strong> (rozkład symetryczny): <strong>odchylenie standardowe</strong> lub wariancję. Przy <strong>medianie</strong> (rozkład mocno skośny): <strong>rozstęp międzykwartylowy</strong> (IQR).</p>", "src": "Miary rozproszenia", "k": ["przy średniej: SD lub wariancja", "przy medianie: IQR"], "u": "wyklad-3.html", "s": "s7"}, {"id": "metodologia/wyklad-3-fiszki:0c9a448c", "q": "Jak definiuje się wariancję i dlaczego podnosi się odchylenia do kwadratu?", "a": "<p>To <strong>suma kwadratów odchyleń od średniej</strong> podzielona przez <strong>n − 1</strong> (w próbie). Kwadraty są potrzebne, bo zwykłe odchylenia od średniej <strong>sumują się do zera</strong>.</p>", "src": "Miary rozproszenia", "k": ["suma kwadratów odchyleń / (n − 1)", "odchylenia sumują się do zera"], "u": "wyklad-3.html", "s": "s7"}, {"id": "metodologia/wyklad-3-fiszki:9b1372ee", "q": "Dlaczego w wariancji z próby dzieli się przez n − 1, a nie przez n?", "a": "<p>Bo próba to wycinek populacji, a nie wszystkie obserwacje: przez n dzieli się tylko przy całej, w pełni przebadanej populacji (σ²). W próbie (s²) mianownik to n − 1.</p>", "src": "Miary rozproszenia", "k": ["próba to wycinek populacji", "n tylko dla całej populacji"], "u": "wyklad-3.html", "s": "s7"}, {"id": "metodologia/wyklad-3-fiszki:4b4ea1c0", "q": "Dlaczego zamiast wariancji podaje się zwykle odchylenie standardowe?", "a": "<p>Wariancja jest w jednostkach <strong>podniesionych do kwadratu</strong> (np. „oceny do kwadratu”), co utrudnia interpretację. <strong>SD = √wariancji</strong> wraca do zwykłych jednostek pomiaru.</p>", "src": "Miary rozproszenia", "k": ["wariancja w jednostkach do kwadratu", "SD w jednostkach pomiaru"], "u": "wyklad-3.html", "s": "s7"}, {"id": "metodologia/wyklad-3-fiszki:16ca3c35", "q": "Do czego służy współczynnik zmienności i jak go liczyć?", "a": "<p><strong>V = SD / M · 100%</strong>. Pozwala porównać zmienność zmiennych o różnych średnich i jednostkach. Poniżej 25% to mała zmienność, 25–50% umiarkowana, 51–100% duża, powyżej 100% bardzo duża.</p>", "src": "Miary rozproszenia", "k": ["V = SD / M · 100%", "porównanie zmiennych o różnych średnich i jednostkach", "< 25% mała zmienność"], "u": "wyklad-3.html", "s": "s7"}, {"id": "metodologia/wyklad-3-fiszki:046e60e4", "q": "Czym jest rozstęp międzykwartylowy?", "a": "<p><strong>IQR = Q<sub>3</sub> − Q<sub>1</sub></strong>: szerokość przedziału zawierającego <strong>50% środkowych</strong> wartości. Pozycyjny odpowiednik SD, w jednostkach badanej cechy.</p>", "src": "Miary rozproszenia", "k": ["IQR = Q3 − Q1", "50% środkowych wartości", "pozycyjny odpowiednik SD"], "u": "wyklad-3.html", "s": "s7"}, {"id": "metodologia/wyklad-3-fiszki:941559e5", "q": "Jak brzmi reguła trzech sigm?", "a": "<p>W rozkładzie normalnym w przedziale <strong>M ± 1 SD</strong> mieści się około <strong>68,3%</strong> wyników, w <strong>± 2 SD</strong> około <strong>95,5%</strong>, a w <strong>± 3 SD</strong> około <strong>99,7%</strong>.</p>", "src": "Rozkład normalny i standaryzacja", "k": ["±1 SD ≈ 68%", "±2 SD ≈ 95%", "±3 SD ≈ 99,7%"], "u": "wyklad-3.html", "s": "s8"}, {"id": "metodologia/wyklad-3-fiszki:31d32e01", "q": "Jak oblicza się wynik Z i co oznacza Z = 2?", "a": "<p><strong>Z = (x − M) / SD</strong>. Z = 2 oznacza wynik <strong>dwa odchylenia standardowe powyżej średniej</strong> (np. 6000 PLN przy M = 4000 i SD = 1000). Rozkład Z ma średnią 0 i SD 1.</p>", "src": "Rozkład normalny i standaryzacja", "k": ["Z = (x − M) / SD", "Z = 2: dwa SD powyżej średniej", "rozkład Z: M = 0, SD = 1"], "u": "wyklad-3.html", "s": "s8"}, {"id": "metodologia/wyklad-3-fiszki:b8429d59", "q": "Czym różni się odchylenie standardowe od błędu standardowego?", "a": "<p><strong>SD</strong> to miara <strong>rozproszenia</strong> wyników w jednej próbie (rozkład w próbie, miara opisowa). <strong>SE</strong> to miara <strong>precyzji</strong> oszacowania: o ile średnio myliłaby się średnia w kolejnych próbach (rozkład próbkowania). SE = √(var / n) = SD / √n.</p>", "src": "Błąd standardowy i przedział ufności", "k": ["SD: rozproszenie w próbie", "SE: precyzja oszacowania średniej", "SE = SD / √n"], "u": "wyklad-3.html", "s": "s9"}, {"id": "metodologia/wyklad-3-fiszki:2f79c205", "q": "Jak układają się M, Me i Mo w rozkładzie prawoskośnym i lewoskośnym?", "a": "<p><strong>Prawoskośny</strong> (skośność &gt; 0, dłuższe prawe ramię): Mo &lt; Me &lt; M, średnia zawyżona. <strong>Lewoskośny</strong> (skośność &lt; 0, dłuższe lewe ramię): M &lt; Me &lt; Mo, średnia zaniżona. Przy asymetrii lepiej opisywać dane miarami pozycyjnymi.</p>", "src": "Kształt rozkładu: skośność i kurtoza", "k": ["prawoskośny: Mo < Me < M", "lewoskośny: M < Me < Mo", "przy asymetrii miary pozycyjne"], "u": "wyklad-3.html", "s": "s10"}, {"id": "metodologia/wyklad-3-fiszki:de29cc8b", "q": "Co oznacza dodatnia i ujemna kurtoza?", "a": "<p><strong>Dodatnia</strong>: rozkład <strong>leptokurtyczny</strong>; według Józefackiej grubsze ogony i większa szansa outlierów (powyżej 2, czasem od 1,5, szukaj obserwacji odstających), według Drogowskazu silne skupienie wokół średniej. <strong>Ujemna</strong>: <strong>platykurtyczny</strong>; małe ogony, w zasadzie brak outlierów (Józefacka), duże rozproszenie wokół środka (Drogowskaz). Rozkład normalny: 0, mezokurtyczny.</p>", "src": "Kształt rozkładu: skośność i kurtoza", "k": ["dodatnia: leptokurtyczny", "ujemna: platykurtyczny", "normalny: 0 (mezokurtyczny)"], "u": "wyklad-3.html", "s": "s10"}, {"id": "metodologia/wyklad-3-fiszki:99e93265", "q": "Jak interpretować wynik testu normalności rozkładu?", "a": "<p>Hipoteza zerowa zakłada <strong>zgodność z rozkładem normalnym</strong>. <strong>p &lt; 0,05</strong> oznacza, że rozkład istotnie odstaje od normalnego (wtedy nie stosuje się testów parametrycznych wymagających normalności); <strong>p &gt; 0,05</strong> to dobra wiadomość. Zapis: W(87) = 0,89; p &lt; 0,001.</p>", "src": "Testy normalności rozkładu", "k": ["H0: rozkład normalny", "p < 0,05: odstaje od normalnego", "p > 0,05: dobra wiadomość"], "u": "wyklad-3.html", "s": "s11"}, {"id": "metodologia/wyklad-3-fiszki:b4c3efb1", "q": "Kiedy stosuje się test Shapiro-Wilka, a kiedy Kołmogorowa-Smirnowa?", "a": "<p><strong>Drogowskaz:</strong> S-W poniżej 100 przypadków, K-S powyżej 100. <strong>Józefacka:</strong> S-W dla 3–5000 obserwacji, bezwzględnie poniżej 50; K-S ma niższą moc, więc tylko przy bardzo dużych próbach (n &gt; 2000). Przy n &gt; 100 oglądaj też histogram oraz skośność i kurtozę (przedział −2 do 2).</p>", "src": "Testy normalności rozkładu", "k": ["Shapiro-Wilk dla mniejszych prób", "K-S dla dużych prób", "K-S ma niższą moc", "przy dużych: histogram, skośność, kurtoza"], "u": "wyklad-3.html", "s": "s11"}, {"id": "metodologia/wyklad-4-fiszki:1ac6b571", "q": "Jakie są cztery podstawowe cele badań naukowych?", "a": "<p><strong>Opis</strong> (charakterystyka zjawiska), <strong>wyjaśnienie</strong> (przyczyny, często pośrednio przez współwystępowanie), <strong>predykcja</strong> (przewidywanie na podstawie predyktora) i <strong>aplikacja</strong> (zastosowanie w praktyce, ocena skuteczności).</p>", "src": "Józefacka i in., t. 1", "k": ["opis", "wyjaśnienie", "predykcja", "aplikacja"], "u": "wyklad-4.html", "s": "s1"}, {"id": "metodologia/wyklad-4-fiszki:39086fe7", "q": "Czym jest problem badawczy i dlaczego cel trzeba uszczegółowić?", "a": "<p><strong>Problem badawczy</strong> to ograniczony obszar zagadnienia z luką w wiedzy lub nową perspektywą, którego rozwiązanie wspiera dziedzinę. Cel trzeba <strong>zawęzić</strong> do konkretnych zmiennych (np. związek wielkości samolotu z lękiem), bo w jednym projekcie nie zbada się wszystkich czynników; pomagają przegląd literatury, obserwacja i rozmowy z ekspertami.</p>", "src": "Józefacka i in., t. 1", "k": ["luka w wiedzy", "ograniczony obszar", "zawężenie do zmiennych", "przegląd literatury"], "u": "wyklad-4.html", "s": "s1"}, {"id": "metodologia/wyklad-4-fiszki:a66e1515", "q": "Jakie cechy ma dobre pytanie badawcze?", "a": "<p>Jest <strong>skoncentrowane</strong> na jednym, możliwym do zbadania problemie, <strong>jasne</strong>, <strong>zwięzłe</strong>, <strong>wystarczająco złożone</strong> (nie „tak/nie”, odpowiedzi nie da się podać przed badaniem) i <strong>dyskutowalne</strong>.</p>", "src": "Józefacka i in., t. 1", "k": ["skoncentrowane, badalne", "jasne i zwięzłe", "złożone (nie tak/nie)", "dyskutowalne"], "u": "wyklad-4.html", "s": "s2"}, {"id": "metodologia/wyklad-4-fiszki:4f15c0cc", "q": "Na czym polegają schematy PICO i PFO?", "a": "<p><strong>PICO</strong> (badania skuteczności interwencji): Patient – kogo badamy, Intervention – interwencja, Comparison – z czym porównujemy, Outcome – wynik. <strong>PFO</strong> (badania predykcyjne): Population, Factors (predyktory), Outcomes.</p>", "src": "Józefacka i in., t. 1", "k": ["PICO – interwencje", "pacjent, interwencja, porównanie, wynik", "PFO – predykcja", "populacja, czynniki, wynik"], "u": "wyklad-4.html", "s": "s2"}, {"id": "metodologia/wyklad-4-fiszki:c1bbd6f5", "q": "Podaj przykłady hipotezy kierunkowej i niekierunkowej dotyczącej różnicy.", "a": "<p>Kierunkowa: „Osoby oglądające przed startem »Katastrofy w przestworzach« mają <strong>wyższy</strong> poziom lęku <strong>niż</strong> oglądające »Kuchenne rewolucje«”. Niekierunkowa: „…<strong>różnią się</strong> poziomem lęku od…”. Kierunkowa określa, która grupa ma wyższy wynik.</p>", "src": "Józefacka i in., t. 1", "k": ["kierunkowa wskazuje, kto wyżej", "niekierunkowa: „różnią się”", "spójnik „niż”"], "u": "wyklad-4.html", "s": "s3"}, {"id": "metodologia/wyklad-4-fiszki:6dca530c", "q": "Czym różnią się hipotezy dotyczące różnicy, związku i wpływu?", "a": "<p><strong>Różnica</strong>: porównanie zmiennej w co najmniej dwóch stanach/grupach („niż”). <strong>Związek</strong>: współzmienność dwóch zmiennych („im… tym…”). <strong>Wpływ</strong>: zmienna X oddziałuje na Y – wymaga eksperymentu.</p>", "src": "Józefacka i in., t. 1", "k": ["różnica – grupy, „niż”", "związek – „im… tym…”", "wpływ – X na Y", "wpływ wymaga eksperymentu"], "u": "wyklad-4.html", "s": "s3"}, {"id": "metodologia/wyklad-4-fiszki:a0e819bb", "q": "Czym różnią się badania podstawowe od stosowanych, a laboratoryjne od terenowych?", "a": "<p><strong>Podstawowe</strong> dają nową wiedzę bez nastawienia na zastosowanie, <strong>stosowane</strong> są nastawione na praktykę. <strong>Laboratoryjne</strong> zapewniają pełną kontrolę warunków (można badać wpływ), ale są sztuczne; <strong>terenowe</strong> są naturalne i kontekstowe, ale słabiej kontrolują zmienne zakłócające.</p>", "src": "Józefacka i in., t. 1", "k": ["podstawowe – wiedza", "stosowane – praktyka", "laboratorium – kontrola, sztuczność", "teren – naturalność, mniej kontroli"], "u": "wyklad-4.html", "s": "s4"}, {"id": "metodologia/wyklad-4-fiszki:4ca5f506", "q": "Czym różni się realizm sytuacyjny od eksperymentalnego?", "a": "<p><strong>Realizm sytuacyjny</strong>: na ile sytuacja badania przypomina prawdziwe życie. <strong>Realizm eksperymentalny</strong>: na ile badani są naprawdę zaangażowani poznawczo, emocjonalnie i behawioralnie w procedurę, co pozwala uogólniać efekty poza laboratorium.</p>", "src": "Józefacka i in., t. 1", "k": ["sytuacyjny – podobieństwo do życia", "eksperymentalny – zaangażowanie badanych", "uogólnianie efektów"], "u": "wyklad-4.html", "s": "s4"}, {"id": "metodologia/wyklad-4-fiszki:3adcf693", "q": "Czym różnią się badania ilościowe od jakościowych?", "a": "<p><strong>Ilościowe</strong>: dane liczbowe i analiza statystyczna (np. średnie z kwestionariusza porównane w grupach). <strong>Jakościowe</strong>: dogłębna analiza treści (wywiady, studia przypadku, obserwacje), wyniki jako opis słowny, bez wnioskowania statystycznego. Główna różnica to sposób zbierania danych i pomiaru.</p>", "src": "Józefacka i in., t. 1", "k": ["ilościowe – liczby, statystyka", "jakościowe – opis słowny", "różnica w sposobie pomiaru"], "u": "wyklad-4.html", "s": "s4"}, {"id": "metodologia/wyklad-4-fiszki:d823b10c", "q": "Czym jest zmienna zależna i niezależna w eksperymencie?", "a": "<p><strong>Zmienna zależna</strong> (Y, wyjaśniana) – mierzona, jej wartość jest nieznana przy planowaniu i zmienia się pod wpływem manipulacji. <strong>Zmienna niezależna</strong> (X, wyjaśniająca, grupująca) – jej poziomy ustala badacz, zakładając, że warunkuje zmianę ZZ.</p>", "src": "Józefacka i in., t. 1", "k": ["ZZ – mierzona, wyjaśniana", "ZN – manipulowana, poziomy", "ZN warunkuje ZZ"], "u": "wyklad-4.html", "s": "s5"}, {"id": "metodologia/wyklad-4-fiszki:3efdd472", "q": "Wymień rodzaje zmiennej niezależnej i podaj przykłady.", "a": "<p><strong>Manipulowane</strong>: <strong>sytuacyjna</strong> (różne warunki: muzyka vs żarty w turbulencji), <strong>zadaniowa</strong> (różne zadania: nucenie vs oddychanie), <strong>instruktażowa</strong> (różne instrukcje: oddychać cały lot vs tylko w turbulencji). <strong>Podmiotowa</strong>: cecha osoby (płeć, wykształcenie) – nie da się nią manipulować ani randomizować; daje quasi-eksperyment.</p>", "src": "Józefacka i in., t. 1", "k": ["sytuacyjna", "zadaniowa", "instruktażowa", "podmiotowa – cecha osoby"], "u": "wyklad-4.html", "s": "s5"}, {"id": "metodologia/wyklad-4-fiszki:74715ac8", "q": "Czym jest randomizacja i czym różni się od doboru losowego?", "a": "<p><strong>Randomizacja</strong> to losowy przydział osób już włączonych do badania do grup – każdy ma tę samą szansę trafić do każdego warunku, więc inne cechy rozkładają się losowo. <strong>Dobór losowy</strong> to losowy wybór uczestników z populacji. Mimo randomizacji może wystąpić nierówny rozkład cech – <strong>błąd próbkowania</strong>.</p>", "src": "Józefacka i in., t. 1", "k": ["losowy przydział do grup", "równe szanse", "dobór losowy – z populacji", "błąd próbkowania"], "u": "wyklad-4.html", "s": "s5"}, {"id": "metodologia/wyklad-4-fiszki:7b06cf0e", "q": "Czym jest grupa kontrolna i zmienna zakłócająca?", "a": "<p><strong>Grupa kontrolna</strong> nie podlega manipulacji ZN i pokazuje wyjściowy poziom ZZ; grupa eksperymentalna – podlega. <strong>Zmienna zakłócająca</strong> to czynnik, którego efektu nie da się odróżnić od efektu ZN (np. dłuższa turbulencja w jednej grupie); dane stają się nieinterpretowalne.</p>", "src": "Józefacka i in., t. 1", "k": ["kontrolna – bez manipulacji", "poziom wyjściowy", "zakłócająca nieodróżnialna od ZN", "dane nieinterpretowalne"], "u": "wyklad-4.html", "s": "s5"}, {"id": "metodologia/wyklad-4-fiszki:bb579139", "q": "Czym jest quasi-eksperyment i jakie wnioski pozwala wyciągać?", "a": "<p>To model zbliżony do eksperymentu, ale <strong>bez randomizacji</strong> – gdy ZN jest podmiotowa (np. płeć) albo względy organizacyjne nie pozwalają losować. <strong>Nie uprawnia</strong> do wniosków o wpływie i przyczynowości.</p>", "src": "Józefacka i in., t. 1", "k": ["brak randomizacji", "ZN podmiotowa lub ograniczenia organizacyjne", "brak wniosków przyczynowych"], "u": "wyklad-4.html", "s": "s5"}, {"id": "metodologia/wyklad-4-fiszki:147e3a38", "q": "Czym różni się model eksperymentalny od nieeksperymentalnego?", "a": "<p><strong>Eksperymentalny</strong>: manipulacja ZN, randomizacja, grupy eksperymentalna i kontrolna, zwykle mniejsze, wnioski przyczynowe, wysoka trafność wewnętrzna kosztem zewnętrznej. <strong>Nieeksperymentalny</strong>: bez manipulacji, zmienne współtowarzyszące (predyktory, kryterialna), duże grupy, wnioski o współwystępowaniu i predykcji, nie o przyczynie.</p>", "src": "Józefacka i in., t. 1", "k": ["zmienne: ZN/ZZ vs predyktory/kryterialna", "grupy i randomizacja vs duże próby", "przyczyna vs współwystępowanie", "trafność wewnętrzna vs zewnętrzna"], "u": "wyklad-4.html", "s": "s6"}, {"id": "metodologia/wyklad-4-fiszki:dd8c6d8d", "q": "Czym są predyktor i zmienna kryterialna w badaniu korelacyjnym?", "a": "<p><strong>Predyktor</strong> (zmienna predykcyjna) to zmienna, na podstawie której przewidujemy wynik (np. poczucie humoru), <strong>zmienna kryterialna</strong> (objaśniana) – ta, którą przewidujemy (lęk w turbulencji). Kryterialna jest jedna, predyktorów może być wiele; nie wynika z tego przyczynowość.</p>", "src": "Józefacka i in., t. 1", "k": ["predyktor – przewidujący", "kryterialna – przewidywana", "jedna kryterialna, wiele predyktorów", "brak przyczynowości"], "u": "wyklad-4.html", "s": "s6"}, {"id": "metodologia/wyklad-4-fiszki:fe54d1de", "q": "Czym jest operacjonalizacja i czym różni się definicja teoretyczna od operacyjnej?", "a": "<p><strong>Operacjonalizacja</strong> to łączenie pojęć (konstruktów) ze sposobami ich pomiaru – przeniesienie na grunt empiryczny. <strong>Definicja teoretyczna</strong> opisuje, czym jest konstrukt (co badamy), <strong>operacyjna</strong> – jak dokładnie go mierzymy (np. liczba trafnych procedur w symulowanej awarii albo punkty w teście). Jedna definicja teoretyczna może mieć różne definicje operacyjne.</p>", "src": "Józefacka i in., t. 1", "k": ["konstrukt nieobserwowalny", "teoretyczna – co", "operacyjna – jak mierzymy", "różne operacjonalizacje"], "u": "wyklad-4.html", "s": "s7"}, {"id": "metodologia/wyklad-4-fiszki:0e037fcb", "q": "Czym różni się kowariancja od współczynnika r-Pearsona?", "a": "<p><strong>Kowariancja</strong> (suma iloczynów odchyleń od średnich / N − 1) pokazuje tylko kierunek związku, jest niewystandaryzowana i zależy od jednostek. <strong>r-Pearsona</strong> to wystandaryzowana kowariancja (ΣZ<sub>x</sub>Z<sub>y</sub>/(N − 1)), pokazuje kierunek i siłę, nie zależy od jednostek, przyjmuje wartości od −1 do 1.</p>", "src": "Bedyńska i Cypryańska", "k": ["kowariancja – tylko kierunek", "zależy od jednostek", "r – wystandaryzowana", "od −1 do 1, siła i kierunek"], "u": "wyklad-4.html", "s": "s8"}, {"id": "metodologia/wyklad-4-fiszki:7f3f39f3", "q": "Jak interpretować siłę i kierunek korelacji r-Pearsona?", "a": "<p><strong>Siła</strong> (|r|): 0–0,30 brak lub bardzo słaba, 0,31–0,50 umiarkowana, 0,51–0,70 silna, 0,71–1 bardzo silna. <strong>Kierunek</strong>: dodatnia – wysokim wartościom jednej zmiennej towarzyszą wysokie drugiej; ujemna – wysokim towarzyszą niskie; zerowa – brak związku liniowego. Interpretuje się tylko korelacje istotne (p &lt; 0,05).</p>", "src": "Bedyńska i Cypryańska", "k": ["progi 0,3 / 0,5 / 0,7", "dodatnia i ujemna", "zerowa", "tylko istotne"], "u": "wyklad-4.html", "s": "s8"}, {"id": "metodologia/wyklad-4-fiszki:490173d4", "q": "Do czego służy wykres rozrzutu i linia dopasowania?", "a": "<p>Wykres rozrzutu pokazuje pary obserwacji jako punkty i pozwala ocenić <strong>kształt</strong> związku (liniowy czy nie, obserwacje odstające). Linię dopasowania wyznacza się <strong>metodą najmniejszych kwadratów</strong> (minimalna suma kwadratów odległości punktów od linii); im bliżej linii punkty, tym trafniejsza predykcja. Dodatnia: od lewego dolnego do prawego górnego rogu.</p>", "src": "Bedyńska i Cypryańska", "k": ["kształt związku", "obserwacje odstające", "metoda najmniejszych kwadratów", "kierunek linii"], "u": "wyklad-4.html", "s": "s8"}, {"id": "metodologia/wyklad-4-fiszki:8125aa8b", "q": "Dlaczego korelacji nie wolno interpretować przyczynowo? Czym jest korelacja pozorna?", "a": "<p>Korelacja mówi tylko o <strong>współwystępowaniu</strong>: nie wiadomo, czy stres obniża wyniki, czy słabe wyniki zwiększają stres. <strong>Korelacja pozorna</strong> to związek, który istnieje dzięki <strong>trzeciej zmiennej</strong> (np. nici dentystyczne i golf – zamożność kraju; towarzyskość i zadowolenie – liczba znajomych).</p>", "src": "Bedyńska i Cypryańska", "k": ["tylko współwystępowanie", "kierunek nieznany", "pozorna – trzecia zmienna", "przykład"], "u": "wyklad-4.html", "s": "s9"}, {"id": "metodologia/wyklad-4-fiszki:c18a6570", "q": "Czego uczy kwartet Anscombe'a i jakie inne pułapki ma korelacja?", "a": "<p>Cztery zbiory mają niemal identyczne r ≈ 0,82, a tylko jeden przedstawia związek liniowy; inne to związek <strong>krzywoliniowy</strong>, związek zniekształcony przez <strong>obserwację odstającą</strong> i brak związku poza jednym punktem. Wniosek: zawsze robić <strong>wykres rozrzutu</strong>. Inna pułapka: <strong>ograniczony zakres</strong> – związek nie jest taki sam w całym zakresie zmiennej.</p>", "src": "Bedyńska i Cypryańska", "k": ["to samo r, różne dane", "krzywoliniowość", "obserwacje odstające", "wykres rozrzutu", "ograniczony zakres"], "u": "wyklad-4.html", "s": "s9"}, {"id": "metodologia/wyklad-4-fiszki:1895f570", "q": "Jaki współczynnik korelacji zastosować w zależności od skali pomiaru?", "a": "<p>Dwie zmienne ilościowe – <strong>r-Pearsona</strong>; porządkowe – <strong>rho Spearmana</strong> lub <strong>tau-b Kendalla</strong>; nominalne 2×2 – <strong>phi</strong>; nominalne o więcej kategoriach – <strong>V Cramera</strong> (0–1, bez kierunku); ilościowa z nominalną – <strong>eta</strong>.</p>", "src": "Bedyńska i Cypryańska", "k": ["Pearson – ilościowe", "Spearman, Kendall – porządkowe", "phi, V Cramera – nominalne", "eta – ilościowa + nominalna"], "u": "wyklad-4.html", "s": "s9"}, {"id": "metodologia/wyklad-4-fiszki:146d6058", "q": "Na czym polega test chi-kwadrat dla tabel krzyżowych?", "a": "<p>Sprawdza, czy dwie zmienne <strong>kategorialne</strong> są ze sobą związane. Porównuje liczebności <strong>obserwowane</strong> z <strong>oczekiwanymi</strong> przy niezależności (E = suma wiersza × suma kolumny / N). Df = (k₁ − 1)(k₂ − 1). Zapis: χ²(1, N = 4950) = 63,50; p &lt; 0,001 – zmienne są powiązane.</p>", "src": "Bedyńska i Cypryańska", "k": ["zmienne kategorialne", "obserwowane vs oczekiwane", "stopnie swobody", "zapis wyniku"], "u": "wyklad-4.html", "s": "s10"}, {"id": "metodologia/wyklad-4-fiszki:6460a044", "q": "Do czego służą reszty standaryzowane i miary siły związku w teście chi-kwadrat?", "a": "<p>Istotny chi-kwadrat mówi tylko, że związek jest. <strong>Reszty standaryzowane</strong> ((O − E)/√E) pokazują, które komórki odbiegają od oczekiwań – istotnie, gdy |reszta| &gt; 1,96 (lub 2,58). Siłę związku opisują współczynnik kontyngencji, <strong>phi</strong> (2×2), <strong>V Cramera</strong> i iloraz szans.</p>", "src": "Bedyńska i Cypryańska", "k": ["istotność ≠ kształt związku", "reszty > 1,96", "phi, V Cramera", "iloraz szans"], "u": "wyklad-4.html", "s": "s10"}, {"id": "metodologia/wyklad-4-fiszki:4ae53c4e", "q": "Kiedy stosuje się poprawkę Yatesa, dokładny test Fishera i chi-kwadrat jako test założeń?", "a": "<p><strong>Poprawka na ciągłość (Yates)</strong> – tylko tabele 2×2. <strong>Dokładny test Fishera</strong> – tabele 2×2, gdy N &lt; 30 lub liczebność oczekiwana w komórce &lt; 5. Chi-kwadrat służy też do sprawdzania <strong>równoliczności grup</strong> przed innymi testami – wtedy pożądany jest wynik nieistotny.</p>", "src": "Bedyńska i Cypryańska", "k": ["Yates – 2×2", "Fisher – małe liczebności", "test założeń: wynik nieistotny"], "u": "wyklad-4.html", "s": "s10"}, {"id": "metodologia/wyklad-4-fiszki:47e91351", "q": "Kiedy stosujemy testy t-Studenta i jakie są ich trzy rodzaje?", "a": "<p>Gdy porównujemy <strong>dwie średnie</strong>, ZZ jest <strong>ilościowa</strong>, a ZN dwuwartościowa. <strong>Dla prób niezależnych</strong> – różne osoby w grupach; <strong>dla prób zależnych</strong> – te same osoby dwa razy (pomiar powtarzany); <strong>dla jednej próby</strong> – średnia z próby vs wartość teoretyczna lub empiryczna.</p>", "src": "Bedyńska i Cypryańska", "k": ["dwie średnie, ZZ ilościowa", "próby niezależne", "próby zależne", "jedna próba vs wartość"], "u": "wyklad-4.html", "s": "s11"}, {"id": "metodologia/wyklad-4-fiszki:6b00f618", "q": "Jakie są zalety i wady pomiaru powtarzanego (prób zależnych)?", "a": "<p>Zaleta: te same osoby w obu warunkach, więc mniej zakłóceń wynikających z <strong>różnic indywidualnych</strong>. Wady: <strong>efekt wprawy</strong>, wpływ pierwszego pomiaru na drugi, czasem absurdalność procedury dla badanego. Kontroluje się to m.in. <strong>zmianą kolejności</strong> warunków.</p>", "src": "Bedyńska i Cypryańska", "k": ["mniej różnic indywidualnych", "efekt wprawy", "wpływ pierwszego pomiaru", "zmiana kolejności"], "u": "wyklad-4.html", "s": "s11"}, {"id": "metodologia/wyklad-4-fiszki:a4a8ecf0", "q": "Jakie są założenia testów t i jak radzić sobie z ich naruszeniem?", "a": "<p>ZZ <strong>ilościowa</strong>, rozkład <strong>zbliżony do normalnego</strong>, dla prób niezależnych <strong>jednorodność wariancji</strong> (test Levene'a: nieistotny → jednorodne; istotny → wiersz z poprawką) i podobna <strong>liczebność</strong> grup. Testy t są dość odporne, zwłaszcza przy równych grupach i N &gt; 30. Przy poważnych naruszeniach: <strong>U Manna-Whitneya</strong> (niezależne) lub <strong>Wilcoxon</strong> (zależne) – oparte na rangach, ale bardziej konserwatywne.</p>", "src": "Bedyńska i Cypryańska", "k": ["skala ilościowa, normalność", "Levene – jednorodność wariancji", "równoliczność, odporność", "U Manna-Whitneya, Wilcoxon"], "u": "wyklad-4.html", "s": "s11"}, {"id": "metodologia/wyklad-4-fiszki:cdd48b7d", "q": "Na czym polega testowanie hipotezy zerowej i co oznacza wynik istotny statystycznie?", "a": "<p>Wnioskowanie jest <strong>indukcyjne</strong> (z próby o populacji) i <strong>pośrednie</strong>: zakładamy H₀ (brak różnicy) i szacujemy, jak prawdopodobny jest uzyskany wynik przy jej prawdziwości. Jeśli p &lt; 0,05 (umowny poziom), odrzucamy H₀ na rzecz H₁. <strong>Wynik istotny</strong> = taka różnica byłaby bardzo mało prawdopodobna, gdyby H₀ była prawdziwa. H₀ i H₁ muszą się wykluczać.</p>", "src": "Bedyńska i Cypryańska", "k": ["H₀ – brak różnicy", "p < 0,05 – odrzucenie H₀", "wnioskowanie pośrednie i indukcyjne", "istotny = mało prawdopodobny przy H₀"], "u": "wyklad-4.html", "s": "s11"}, {"id": "metodologia/wyklad-4-fiszki:bb48064a", "q": "Czym jest d Cohena i jak je interpretować?", "a": "<p>To miara <strong>wielkości efektu</strong> dla różnicy dwóch średnich – istotność nie mówi o sile efektu (przy dużej próbie nawet mała różnica bywa istotna). Progi Cohena: <strong>0,20 mały, 0,50 średni, 0,80 duży</strong>. Dla prób zależnych d = średnia różnic / SD różnic.</p>", "src": "Bedyńska i Cypryańska", "k": ["wielkość efektu", "istotność ≠ siła", "0,2 / 0,5 / 0,8"], "u": "wyklad-4.html", "s": "s11"}, {"id": "metodologia/wyklad-4-fiszki:46029441", "q": "Jak poprawnie zapisać wynik testu t w raporcie?", "a": "<p>Podać średnie i odchylenia grup, statystykę t ze stopniami swobody, p i d, np. „Średnia ocen własnej towarzyskości (M = 4,95; SD = 1,47) była istotnie wyższa niż ocen przeciętnego studenta (M = 4,00; SD = 1,34), t(19) = 4,79; p &lt; 0,001; d = 1,07”. Odnosimy się do hipotezy badawczej, <strong>nie wspominamy o H₀</strong>; p = 0,000 zapisujemy jako p &lt; 0,001.</p>", "src": "Bedyńska i Cypryańska", "k": ["M i SD grup", "t(df), p, d", "bez wzmianki o H₀", "p < 0,001 zamiast 0,000"], "u": "wyklad-4.html", "s": "s11"}, {"id": "metodologia/cwiczenia-3-fiszki:08e06f99", "q": "Czym jest korelacja i czego uczy przykład bocianów i dzieci?", "a": "<p>Korelacja to sytuacja, w której dwie zmienne są ze sobą <strong>powiązane</strong> (współwystępują). Matthews znalazł istotną (p = 0,008) i silną korelację liczby bocianów i urodzeń w 17 krajach – to przykład mylenia <strong>współwystępowania z przyczynowością</strong> i <strong>korelacji pozornej</strong>: obie zmienne zależą od wielkości kraju (trzecia zmienna).</p>", "src": "Józefacka i in., t. 1", "k": ["współwystępowanie dwóch zmiennych", "korelacja ≠ przyczynowość", "korelacja pozorna", "trzecia zmienna (wielkość kraju)"], "u": "cwiczenia-3.html", "s": "s1"}, {"id": "metodologia/cwiczenia-3-fiszki:a13d8c87", "q": "Jak oblicza się kowariancję i czym różni się od współczynnika korelacji?", "a": "<p>Kowariancja: średnie obu zmiennych → odchylenia wyników od średnich → iloczyny odchyleń → suma → podział przez N − 1. Mówi tylko o <strong>kierunku</strong> związku, nie o sile. Współczynnik r Pearsona liczy się tak samo po zamianie wyników na <strong>skalę Z</strong> – to wystandaryzowana kowariancja od −1 do +1, pokazująca kierunek i siłę.</p>", "src": "Józefacka i in., t. 1", "k": ["kroki: odchylenia, iloczyny, suma, N − 1", "kowariancja – tylko kierunek", "r – po standaryzacji (Z)", "od −1 do +1"], "u": "cwiczenia-3.html", "s": "s2"}, {"id": "metodologia/cwiczenia-3-fiszki:1bf6df76", "q": "Jak testuje się istotność korelacji i jak brzmią hipotezy?", "a": "<p>H₀: w populacji r = 0 (brak związku); H₁: r ≠ 0 (zwykle bezkierunkowo, test dwustronny). Statystykę opartą na rozkładzie <strong>t Studenta</strong> porównuje się z wartością krytyczną dla danych df i α. Test zależy od liczebności: przy dużej próbie nawet słaba korelacja może być istotna.</p>", "src": "Józefacka i in., t. 1", "k": ["H₀: r = 0", "H₁: r ≠ 0", "rozkład t, df", "duża próba → istotne nawet słabe"], "u": "cwiczenia-3.html", "s": "s2"}, {"id": "metodologia/cwiczenia-3-fiszki:68946033", "q": "Wymień założenia korelacji r Pearsona.", "a": "<p>Dwie zmienne <strong>ilościowe</strong>; dane <strong>sparowane</strong> (oba wyniki dla każdej obserwacji); obserwacje <strong>niezależne</strong> (różne osoby, nie powtarzane pomiary). Diagnostyka: <strong>prostoliniowość</strong>, brak (wpływowych) <strong>obserwacji odstających</strong>, <strong>normalność</strong> rozkładu próbkowania (ważna przy n &lt; 30).</p>", "src": "Józefacka i in., t. 1", "k": ["dwie zmienne ilościowe", "dane sparowane", "niezależne obserwacje", "prostoliniowość", "odstające", "normalność przy n < 30"], "u": "cwiczenia-3.html", "s": "s3"}, {"id": "metodologia/cwiczenia-3-fiszki:61e76074", "q": "Dlaczego dane z powtarzanych pomiarów tej samej osoby nie nadają się do korelacji r Pearsona?", "a": "<p>Łamią założenie <strong>niezależności obserwacji</strong>: wszystkie dane pochodzą z jednego źródła i są ze sobą powiązane. Dla takich danych lepszy jest test t lub ANOVA dla pomiarów powtarzanych.</p>", "src": "Józefacka i in., t. 1", "k": ["niezależność obserwacji", "jedno źródło danych", "t / ANOVA dla pomiarów powtarzanych"], "u": "cwiczenia-3.html", "s": "s3"}, {"id": "metodologia/cwiczenia-3-fiszki:de33aab0", "q": "Jak odczytać kierunek i siłę związku z wykresu rozrzutu?", "a": "<p>Chmurę punktów zamyka się w elipsę: nachylona w prawo – korelacja <strong>dodatnia</strong>, w lewo – <strong>ujemna</strong>, bezkształtna chmura – brak związku. <strong>Im węższa elipsa, tym silniejszy związek</strong>; przy r = ±1 punkty leżą na prostej. Zerowa korelacja nie wyklucza związku <strong>nieliniowego</strong>.</p>", "src": "Józefacka i in., t. 1", "k": ["elipsa w prawo – dodatnia", "w lewo – ujemna", "węższa – silniejsza", "r = 0 ≠ brak związku nieliniowego"], "u": "cwiczenia-3.html", "s": "s3"}, {"id": "metodologia/cwiczenia-3-fiszki:0e3e3d82", "q": "Czego uczą kwartet Anscombe'a i Datasaurus?", "a": "<p>Zbiory o identycznych średnich, wariancjach i korelacji (r = 0,816 u Anscombe'a; r = −0,06 dla Datasaurusa) mogą wyglądać zupełnie inaczej: związek liniowy, krzywoliniowy, z wpływową obserwacją odstającą albo korelacja pozorna tworzona przez jeden punkt. Bez <strong>wykresu rozrzutu</strong> nie da się poprawnie zinterpretować r.</p>", "src": "Józefacka i in., t. 1", "k": ["te same statystyki, różne dane", "krzywoliniowość, odstające", "pozorna przez jeden punkt", "zawsze wykres rozrzutu"], "u": "cwiczenia-3.html", "s": "s3"}, {"id": "metodologia/cwiczenia-3-fiszki:e6e2c9b6", "q": "Jak krok po kroku zinterpretować wynik korelacji r Pearsona?", "a": "<p>1) <strong>p</strong>: czy związek jest istotny (p &lt; 0,05); jeśli nie – brak podstaw do odrzucenia H₀. 2) <strong>Wykres</strong>: liniowość, brak odstających. 3) <strong>Znak</strong> r: kierunek. 4) <strong>Wartość</strong> r: siła. 5) <strong>R²</strong>: procent wyjaśnionej zmienności. Na koniec ostrożnie z przyczynowością.</p>", "src": "Józefacka i in., t. 1", "k": ["istotność p", "wykres rozrzutu", "kierunek ze znaku", "siła z wartości", "R²"], "u": "cwiczenia-3.html", "s": "s4"}, {"id": "metodologia/cwiczenia-3-fiszki:0a3de770", "q": "Jak interpretować siłę korelacji według Cohena i według Gignaca i Szodoraia?", "a": "<p><strong>Cohen (1988)</strong>: ok. 0,1–0,2 słaba, 0,3–0,5 umiarkowana, ≥ 0,6 silna. <strong>Gignac i Szodorai (2016)</strong>, na podstawie 708 korelacji z 199 metaanaliz (połowa poniżej 0,19, 95% poniżej 0,45): 0,10 słaba, 0,20 umiarkowana, 0,30 i więcej silna. Progi Cohena są dla psychologii zawyżone; warto znać standardy dziedziny.</p>", "src": "Józefacka i in., t. 1", "k": ["Cohen: 0,1 / 0,3 / 0,6", "Gignac i Szodorai: 0,1 / 0,2 / 0,3", "metaanalizy: typowe korelacje niskie", "zależność od dziedziny"], "u": "cwiczenia-3.html", "s": "s4"}, {"id": "metodologia/cwiczenia-3-fiszki:92bf4d1b", "q": "Czym jest współczynnik determinacji i jak go interpretować?", "a": "<p>R² = r², zawsze dodatni. To część zmienności jednej zmiennej wyjaśniana zmiennością drugiej. Dla r = 0,76 → R² = 0,58: liczba książek wyjaśnia 58% zróżnicowania liczby myśli, 42% wyjaśniają inne czynniki. Błąd: traktowanie r = 0,76 jako „76%”.</p>", "src": "Józefacka i in., t. 1", "k": ["R² = r²", "procent wyjaśnionej zmienności", "przykład 0,76 → 58%", "r to nie procent"], "u": "cwiczenia-3.html", "s": "s4"}, {"id": "metodologia/cwiczenia-3-fiszki:ffc5fd8a", "q": "Jakie trzy warunki muszą być spełnione, by mówić o przyczynowości?", "a": "<p>1) Zmienne są ze sobą <strong>powiązane</strong> (korelacja). 2) <strong>Pierwszeństwo czasowe</strong> – przyczyna poprzedza skutek. 3) <strong>Kontrola trzeciej (zakłócającej) zmiennej</strong> – związku nie da się wyjaśnić inaczej. Badania korelacyjne zwykle spełniają tylko pierwszy warunek; przyczynowość wykazuje eksperyment.</p>", "src": "Józefacka i in., t. 1", "k": ["związek", "pierwszeństwo czasowe", "kontrola trzeciej zmiennej", "eksperyment"], "u": "cwiczenia-3.html", "s": "s5"}, {"id": "metodologia/cwiczenia-3-fiszki:de835635", "q": "Na czym polegają problem kierunkowości i problem trzeciej zmiennej?", "a": "<p><strong>Kierunkowość</strong>: z korelacji nie wiadomo, która zmienna wpływa na którą (książki → myśli czy myśli → książki?). <strong>Trzecia zmienna</strong>: związek może wynikać z czynnika wpływającego na obie (bociany i dzieci – wielkość kraju). W korelacji zmienne są równorzędne; kierunek można próbować badać korelacjami krzyżowymi (pomiary w kilku punktach czasu).</p>", "src": "Józefacka i in., t. 1", "k": ["kierunkowość – co na co", "trzecia zmienna – wspólna przyczyna", "zmienne równorzędne", "korelacje krzyżowe"], "u": "cwiczenia-3.html", "s": "s5"}, {"id": "metodologia/cwiczenia-3-fiszki:8247b32e", "q": "Czym jest tabela krzyżowa i do czego służą sumy brzegowe?", "a": "<p><strong>Tabela krzyżowa</strong> (kontyngencji) przedstawia łączny rozkład dwóch lub więcej zmiennych jakościowych: kategorie jednej w wierszach, drugiej w kolumnach, liczebności w komórkach; wymiary R × C. <strong>Sumy brzegowe</strong> wierszy i kolumn pokazują rozkład każdej zmiennej osobno (który lokal sprzedał więcej, które cygara są popularniejsze); suma ogólna jest w prawym dolnym rogu.</p>", "src": "Józefacka i in., t. 1", "k": ["łączny rozkład zmiennych jakościowych", "wiersze × kolumny, komórki", "sumy brzegowe – każda zmienna osobno", "suma ogólna"], "u": "cwiczenia-3.html", "s": "s6"}, {"id": "metodologia/cwiczenia-3-fiszki:aa2c9a43", "q": "Czym różnią się procenty z wierszy, z kolumn i z całości? Którą strategię wybrać?", "a": "<p><strong>Z kolumn</strong>: komórka / suma kolumny (suma w kolumnie = 100%). <strong>Z wierszy</strong>: komórka / suma wiersza (suma w wierszu = 100%). <strong>Z całości</strong>: komórka / suma ogólna – rzadko. Przyjmuje się <strong>jedną strategię</strong>, zależnie od tego, co jest zmienną niezależną; gdy porównywane grupy są w wierszach, najbardziej użyteczne są procenty z wierszy. Różnice rozstrzyga test chi-kwadrat.</p>", "src": "Józefacka i in., t. 1", "k": ["z kolumn / z wierszy / z całości", "sumy = 100%", "jedna strategia", "grupy w wierszach → procenty z wierszy", "chi-kwadrat rozstrzyga"], "u": "cwiczenia-3.html", "s": "s6"}, {"id": "metodologia/fiszki:9709588d", "q": "Czym różni się dowód anegdotyczny od obserwacji systematycznej?", "a": "<p>Anegdota to pojedyncze, przypadkowe doświadczenie („mnie pomogło”). Obserwacja systematyczna jest zaplanowana, powtarzalna i obejmuje wiele przypadków.</p>", "src": "Sprawdź się", "k": ["anegdota: pojedyncze, przypadkowe", "systematyczna: zaplanowana, powtarzalna, wiele przypadków"], "u": "wyklad-1.html", "s": ""}, {"id": "metodologia/fiszki:f2ea2e19", "q": "Dlaczego poprawny logicznie wniosek dedukcyjny może być fałszywy?", "a": "<p>Bo poprawność logiczna dotyczy tylko formy. Jeśli przesłanka jest fałszywa (np. „wszyscy wykładowcy są wymagający”), wniosek też może być fałszywy.</p>", "src": "Sprawdź się", "k": ["poprawność dotyczy formy", "fałszywa przesłanka"], "u": "wyklad-1.html", "s": "s3"}, {"id": "metodologia/fiszki:ca71b8a4", "q": "Jaki jest główny problem indukcji?", "a": "<p>Działa post factum i nie daje pewności — trzeba zgromadzić dostatecznie wiele dowodów, a i tak może pojawić się „czarny łabędź”.</p>", "src": "Sprawdź się", "k": ["post factum", "brak pewności", "czarny łabędź"], "u": "wyklad-1.html", "s": "s3"}, {"id": "metodologia/fiszki:ae971388", "q": "Czym różnią się nauki formalne od empirycznych?", "a": "<p>Formalne wychodzą od aksjomatów i działają dedukcyjnie. Empiryczne wychodzą od wiedzy z badań lub założeń (nie aksjomatów) i weryfikują hipotezy przez obserwację.</p>", "src": "Sprawdź się", "k": ["formalne: aksjomaty, dedukcja", "empiryczne: weryfikacja przez obserwację"], "u": "wyklad-1.html", "s": "s4"}, {"id": "metodologia/fiszki:810834a0", "q": "Dlaczego w psychologii wniosek z przesłanek to hipoteza, a w fizyce nie musi nią być?", "a": "<p>W fizyce przesłanki mają status praw przyrody. W psychologii opierają się na wariancji prób i błędzie pomiaru albo są tylko założeniem — więc wniosek wymaga weryfikacji.</p>", "src": "Sprawdź się", "k": ["w fizyce prawa przyrody", "w psychologii wariancja i błąd pomiaru", "wniosek wymaga weryfikacji"], "u": "wyklad-1.html", "s": "s4"}, {"id": "metodologia/fiszki:8cc6ac64", "q": "Wymień cztery cele naukowe psychologii.", "a": "<p>Opis, wyjaśnienie, przewidywanie, aplikacja (konstruowanie skutecznych oddziaływań).</p>", "src": "Sprawdź się", "k": ["opis", "wyjaśnienie", "przewidywanie", "aplikacja"], "u": "wyklad-1.html", "s": "s6"}, {"id": "metodologia/fiszki:8c52b71a", "q": "Kto wprowadził zasadę falsyfikowalności i co ona mówi?", "a": "<p>Karl Popper. Hipoteza jest naukowa, jeśli istnieje empiryczna możliwość wykazania, że jest fałszywa.</p>", "src": "Sprawdź się", "k": ["Karl Popper", "możliwość wykazania fałszywości"], "u": "wyklad-1.html", "s": "s5"}, {"id": "metodologia/fiszki:03a71af0", "q": "Czym jest paradygmat?", "a": "<p>Zestawem pojęć i zależności między nimi, który zapoczątkowuje cykl badań i wnioskowania w danym obszarze nauki.</p>", "src": "Sprawdź się", "k": ["zestaw pojęć i zależności", "zapoczątkowuje cykl badań"], "u": "wyklad-1.html", "s": "s7"}, {"id": "metodologia/fiszki:d21d6403", "q": "Kiedy cecha jest stałą, a kiedy zmienną?", "a": "<p>Zmienna przyjmuje co najmniej dwie wartości w badanym zbiorze. Jeśli w tym zbiorze ma tylko jedną wartość — jest stałą, nawet gdy w populacji występuje inaczej.</p>", "src": "Sprawdź się", "k": ["zmienna: co najmniej dwie wartości", "stała: jedna wartość w badanym zbiorze"], "u": "wyklad-1.html", "s": "s10"}, {"id": "metodologia/fiszki:885e1071", "q": "Czym jest replikacja i dlaczego wymaga precyzyjnego opisu?", "a": "<p>Dokładne powtórzenie procedury, by sprawdzić, czy wynik się odtworzy. Bez szczegółowego „przepisu” nie da się powtórzyć badania.</p>", "src": "Sprawdź się", "k": ["dokładne powtórzenie procedury", "sprawdzenie, czy wynik się odtworzy", "wymaga szczegółowego opisu"], "u": "wyklad-1.html", "s": "s8"}, {"id": "metodologia/fiszki:e862a643", "q": "Dlaczego teoria strun to według wykładu hipoteza, a nie teoria empiryczna?", "a": "<p>Jest wyprowadzona dedukcyjnie, ale jej kluczowe twierdzenia (dodatkowe wymiary) są niedostępne doświadczeniu — brak weryfikacji empirycznej.</p>", "src": "Sprawdź się", "k": ["wyprowadzona dedukcyjnie", "twierdzenia niedostępne doświadczeniu", "brak weryfikacji empirycznej"], "u": "wyklad-1.html", "s": "s3"}, {"id": "metodologia/fiszki:52cd2826", "q": "Co według Józefackiej odróżnia naukę od pseudonauki?", "a": "<p>Prawdziwość przesłanek, na których opiera się wnioskowanie — pseudonauka nie ma zaplecza potwierdzonych faktów ani sprawdzalnych hipotez.</p>", "src": "Sprawdź się", "k": ["prawdziwość przesłanek", "brak potwierdzonych faktów i sprawdzalnych hipotez"], "u": "wyklad-1.html", "s": "s9"}, {"id": "metodologia/fiszki:b63364e7", "q": "Ułóż kroki procesu badawczego.", "a": "<p>Pytanie badawcze → hipoteza → zmienne (operacjonalizacja) → zebranie danych → test statystyczny → wynik testu (istotność) → wniosek (przyjęcie / odrzucenie hipotezy).</p>", "src": "Sprawdź się — ćwiczenia", "k": ["pytanie badawcze → hipoteza", "operacjonalizacja zmiennych", "zebranie danych → test", "wniosek o hipotezie"], "u": "cwiczenia-1.html", "s": "c1"}, {"id": "metodologia/fiszki:31367945", "q": "Czym różni się pytanie badawcze od hipotezy?", "a": "<p>Pytanie mówi, czego chcemy się dowiedzieć (forma pytająca). Hipoteza mówi, czego się spodziewamy (zdanie twierdzące).</p>", "src": "Sprawdź się — ćwiczenia", "k": ["pytanie: czego chcemy się dowiedzieć", "hipoteza: czego się spodziewamy (twierdzenie)"], "u": "cwiczenia-1.html", "s": "c1"}, {"id": "metodologia/fiszki:e2aad2d9", "q": "„Czy osoby pracujące zawodowo mają wyższy poziom stresu niż niepracujące?” — jaki to typ pytania i jakie zmienne?", "a": "<p>Pytanie o <b>różnice między grupami</b>. Zmienne: praca zawodowa (nominalna, 0/1) i poziom stresu (ilościowa, np. suma PSS).</p>", "src": "Sprawdź się — ćwiczenia", "k": ["pytanie o różnice między grupami", "praca zawodowa: nominalna", "stres: ilościowa"], "u": "cwiczenia-1.html", "s": ""}, {"id": "metodologia/fiszki:d31742ee", "q": "Wykształcenie: podstawowe / średnie / wyższe. Jaki to poziom pomiaru?", "a": "<p><b>Porządkowy</b> — kategorie mają kolejność, ale odstępy między nimi nie są równe.</p>", "src": "Sprawdź się — ćwiczenia", "k": ["porządkowy", "kolejność bez równych odstępów"], "u": "cwiczenia-1.html", "s": "c2"}, {"id": "metodologia/fiszki:ceca4391", "q": "Odwróć odpowiedź 1 w PSS (skala 0–4).", "a": "<p>(0 + 4) − 1 = <b>3</b>.</p>", "src": "Sprawdź się — ćwiczenia", "k": ["(0 + 4) − 1", "= 3"], "u": "cwiczenia-1.html", "s": "c6"}, {"id": "metodologia/fiszki:a795194f", "q": "Co wpiszesz w Jamovi jako warunek rekodowania dla SWLS3?", "a": "<p><code>8 - $source</code>.</p>", "src": "Sprawdź się — ćwiczenia", "k": ["8 - $source"], "u": "cwiczenia-1.html", "s": "c5"}, {"id": "metodologia/fiszki:2dd1bea0", "q": "Policzyłaś w Jamovi MEAN, a części osób wyszło puste pole. Dlaczego?", "a": "<p>Te osoby mają brak danych w co najmniej jednej pozycji. Jamovi domyślnie wtedy nie liczy wyniku. Argument <code>ignore_missing=1</code> zmienia to zachowanie.</p>", "src": "Sprawdź się — ćwiczenia", "k": ["brak danych w co najmniej jednej pozycji", "ignore_missing=1"], "u": "cwiczenia-1.html", "s": "c5"}, {"id": "metodologia/fiszki:b41dd37c", "q": "Jakie 5 kroków przygotowania bazy przed importem pokazano na zajęciach?", "a": "<p>Usunąć niepotrzebne kolumny; usunąć obserwacje bez zgody; dodać kolumnę ID; zamienić odpowiedzi nominalne na liczby; zmienić nagłówki na krótkie, bez spacji.</p>", "src": "Sprawdź się — ćwiczenia", "k": ["usunąć niepotrzebne kolumny", "usunąć osoby bez zgody", "dodać ID", "odpowiedzi nominalne na liczby", "krótkie nagłówki bez spacji"], "u": "cwiczenia-1.html", "s": "c4"}, {"id": "metodologia/fiszki:4aa14e4b", "q": "Czym różnią się dane surowe od roboczych i na których liczysz?", "a": "<p>Surowe — nieprzekształcone, wprost ze źródła. Robocze — zakodowane, odwrócone, wyczyszczone, ze wskaźnikami. Liczysz na roboczych (na kopii), surowe przechowujesz w kilku miejscach i ich nie ruszasz.</p>", "src": "Sprawdź się — ćwiczenia", "k": ["surowe: wprost ze źródła", "robocze: zakodowane, wyczyszczone", "liczymy na roboczych", "surowych nie ruszamy"], "u": "cwiczenia-1.html", "s": "c7"}, {"id": "metodologia/fiszki:e7e1d7b1", "q": "Badasz osobę dwa razy tym samym testem. Jak to wpisać?", "a": "<p>W jednym wierszu, w sąsiednich kolumnach (np. <code>XYZ_przed</code>, <code>XYZ_po</code>). Jedna osoba = jeden wiersz.</p>", "src": "Sprawdź się — ćwiczenia", "k": ["jeden wiersz", "sąsiednie kolumny (przed/po)"], "u": "cwiczenia-1.html", "s": "c9"}, {"id": "metodologia/fiszki:ee3ee456", "q": "Dlaczego zmienna „płeć” nie powinna mieć typu tekstowego?", "a": "<p>Program (SPSS, Jamovi) nie przeprowadzi analiz liczbowych na zmiennej tekstowej. Koduje się ją liczbami (1, 2) i opisuje w kolumnie WARTOŚCI.</p>", "src": "Sprawdź się — ćwiczenia", "k": ["brak analiz liczbowych na tekście", "kodowanie liczbami z etykietami"], "u": "cwiczenia-1.html", "s": "c10"}, {"id": "metodologia/fiszki:ffaa130f", "q": "Skala 1–5. Jakim kodem oznaczyć brak danych i gdzie go zadeklarować?", "a": "<p>Wartością spoza zakresu, np. 9, wpisaną w kolumnie BRAKI (dyskretne wartości braków danych).</p>", "src": "Sprawdź się — ćwiczenia", "k": ["kod spoza zakresu (np. 9)", "kolumna BRAKI"], "u": "cwiczenia-1.html", "s": ""}, {"id": "metodologia/fiszki:f5c02b78", "q": "Czy ustawienie „Poziom pomiaru: Ilościowa” sprawia, że SPSS wie, jaka to skala?", "a": "<p>Nie. To informacja tylko dla Ciebie — program sam nie rozpoznaje skal. Nie rozróżnia też interwałowej od ilorazowej.</p>", "src": "Sprawdź się — ćwiczenia", "k": ["nie", "informacja tylko dla użytkownika", "nie odróżnia interwałowej od ilorazowej"], "u": "cwiczenia-1.html", "s": "c10"}, {"id": "metodologia/fiszki:5b0aed48", "q": "Odwróć wynik 2 na skali 1–7.", "a": "<p>(7 + 1) − 2 = <b>6</b>.</p>", "src": "Sprawdź się — ćwiczenia", "k": ["(7 + 1) − 2", "= 6"], "u": "cwiczenia-1.html", "s": ""}, {"id": "metodologia/fiszki:b43712d5", "q": "Dlaczego lepiej „Rekoduj na inne zmienne” niż „na te same”?", "a": "<p>„Na te same” nadpisuje oryginalne odpowiedzi — tracisz dane surowe. „Na inne” tworzy nową zmienną i oryginał zostaje.</p>", "src": "Sprawdź się — ćwiczenia", "k": ["„na te same” nadpisuje oryginał", "„na inne” zachowuje dane surowe"], "u": "cwiczenia-1.html", "s": "c13"}, {"id": "metodologia/fiszki:4f711bf7", "q": "Osoba pominęła 1 z 5 pytań. Co da wzór (a+b+c+d+e)/5, a co MEAN(a,b,c,d,e)?", "a": "<p>Wzór → systemowy brak danych (puste pole). MEAN → średnia z 4 ważnych odpowiedzi.</p>", "src": "Sprawdź się — ćwiczenia", "k": ["wzór: brak danych", "MEAN: średnia z 4 ważnych"], "u": "cwiczenia-1.html", "s": "c5"}, {"id": "metodologia/fiszki:1ab5dd65", "q": "Alfa Cronbacha wyszła podejrzanie niska. Co sprawdzić najpierw?", "a": "<p>Czy pozycje odwrócone zostały zrekodowane przed obliczeniem.</p>", "src": "Sprawdź się — ćwiczenia", "k": ["zrekodowanie pozycji odwróconych"], "u": "cwiczenia-1.html", "s": "c12"}, {"id": "metodologia/fiszki:7395bf08", "q": "Ankietowani o wysokich dochodach częściej odmawiają podania dochodu. Jaki to mechanizm?", "a": "<p><b>MNAR</b> — brak zależy od wartości samej zmiennej (dochodu).</p>", "src": "Sprawdź się — ćwiczenia", "k": ["MNAR", "brak zależy od wartości samej zmiennej"], "u": "cwiczenia-1.html", "s": "c14"}, {"id": "metodologia/fiszki:bb00c3aa", "q": "Starsze osoby częściej pomijają pytania o media społecznościowe. Jaki to mechanizm?", "a": "<p><b>MAR</b> — brak zależy od innej zmiennej (wieku).</p>", "src": "Sprawdź się — ćwiczenia", "k": ["MAR", "brak zależy od innej zmiennej"], "u": "cwiczenia-1.html", "s": ""}, {"id": "metodologia/fiszki:8dc25fb5", "q": "Który mechanizm braków można sprawdzić testem statystycznym?", "a": "<p>Tylko <b>MCAR</b>.</p>", "src": "Sprawdź się — ćwiczenia", "k": ["MCAR"], "u": "cwiczenia-1.html", "s": "c14"}, {"id": "metodologia/fiszki:7ed65ab0", "q": "Wyniki analizy wyglądają dziwnie — za mało osób. Gdzie patrzysz?", "a": "<p>Na pasek stanu: czy nie jest włączony <b>Filtr Wł.</b> (albo podział / ważenie).</p>", "src": "Sprawdź się — ćwiczenia", "k": ["pasek stanu", "włączony filtr (lub podział, ważenie)"], "u": "cwiczenia-1.html", "s": ""}, {"id": "metodologia/fiszki:90f8652c", "q": "Co znaczy „wskaźnik” w metodologii, a co „zmienna” w SPSS?", "a": "<p>Wskaźnik to operacjonalizacja zmiennej — liczbowy ekwiwalent definicji operacyjnej. W SPSS „zmienną” jest każda kolumna, więc wskaźnik też.</p>", "src": "Sprawdź się — ćwiczenia", "k": ["wskaźnik: operacjonalizacja zmiennej", "w SPSS zmienna to każda kolumna"], "u": "cwiczenia-1.html", "s": ""}, {"id": "metodologia/fiszki:142512f4", "q": "Czym różni się koncepcja od pojęcia i konstruktu?", "a": "<p>Koncepcja to Twój prywatny obraz mentalny. Pojęcie to uzgodniony termin, który pozwala się o koncepcjach porozumieć („rodzina koncepcji”). Konstrukt to twór teoretyczny oparty na obserwacjach, ale nieobserwowalny ani bezpośrednio, ani pośrednio (np. IQ).</p>", "src": "Sprawdź się — wykład 2", "k": ["koncepcja: prywatny obraz", "pojęcie: uzgodniony termin", "konstrukt: nieobserwowalny twór teoretyczny"], "u": "wyklad-2.html", "s": "d1"}, {"id": "metodologia/fiszki:a0d34ba0", "q": "Wymień trzy klasy rzeczy mierzonych według Kaplana.", "a": "<p>Bezpośrednio obserwowalne, pośrednio obserwowalne, konstrukty.</p>", "src": "Sprawdź się — wykład 2", "k": ["bezpośrednio obserwowalne", "pośrednio obserwowalne", "konstrukty"], "u": "wyklad-2.html", "s": "d1"}, {"id": "metodologia/fiszki:7e59e33d", "q": "Czym jest reifikacja?", "a": "<p>Traktowaniem pojęcia (konstruktu) jak rzeczy realnie istniejącej, z „prawdziwym” znaczeniem.</p>", "src": "Sprawdź się — wykład 2", "k": ["traktowanie konstruktu jak realnej rzeczy"], "u": "wyklad-2.html", "s": "d1"}, {"id": "metodologia/fiszki:9e57488c", "q": "Wskaźnik a wymiar — podaj definicje i przykład.", "a": "<p>Wskaźnik to znak obecności lub nieobecności pojęcia (odwiedzanie szpitali dziecięcych → współczucie). Wymiar to dający się wyszczególnić aspekt pojęcia (współczucie uczuciowe vs behawioralne).</p>", "src": "Sprawdź się — wykład 2", "k": ["wskaźnik: znak obecności pojęcia", "wymiar: wyszczególniony aspekt pojęcia", "przykład: współczucie"], "u": "wyklad-2.html", "s": "d2"}, {"id": "metodologia/fiszki:a7d430ba", "q": "Co mówi zasada wzajemnej wymienialności wskaźników?", "a": "<p>Jeśli różne wskaźniki reprezentują to samo pojęcie, powinny dawać ten sam wzorzec wyników. Wtedy wniosek jest mocny, nawet bez zgody co do najlepszego wskaźnika.</p>", "src": "Sprawdź się — wykład 2", "k": ["różne wskaźniki tego samego pojęcia", "ten sam wzorzec wyników", "mocny wniosek"], "u": "wyklad-2.html", "s": "d2"}, {"id": "metodologia/fiszki:c6558c89", "q": "Definicja realna, nominalna, operacyjna — która jest bezużyteczna w badaniach i dlaczego?", "a": "<p>Realna: próbuje uchwycić „zasadniczą naturę” bytu, więc prowadzi do reifikacji. Badania opierają się na nominalnej (przypisane znaczenie) i operacyjnej (jak dokładnie mierzymy).</p>", "src": "Sprawdź się — wykład 2", "k": ["realna bezużyteczna (reifikacja)", "nominalna: przypisane znaczenie", "operacyjna: jak mierzymy"], "u": "wyklad-2.html", "s": "d2"}, {"id": "metodologia/fiszki:35237c96", "q": "Ułóż kolejność: definicja operacyjna, konceptualizacja, pomiar, definicja nominalna.", "a": "<p>Konceptualizacja → definicja nominalna → definicja operacyjna → pomiar w świecie rzeczywistym.</p>", "src": "Sprawdź się — wykład 2", "k": ["konceptualizacja", "definicja nominalna", "definicja operacyjna", "pomiar"], "u": "wyklad-2.html", "s": ""}, {"id": "metodologia/fiszki:a2d67978", "q": "Dlaczego precyzyjne definicje są ważniejsze w badaniach opisowych niż wyjaśniających?", "a": "<p>W opisie wynik (np. stopa bezrobocia) zależy wprost od definicji. W wyjaśnianiu wzorce zależności (starsi bardziej konserwatywni) zwykle utrzymują się przy różnych definicjach.</p>", "src": "Sprawdź się — wykład 2", "k": ["w opisie wynik zależy od definicji", "w wyjaśnianiu wzorce się utrzymują"], "u": "wyklad-2.html", "s": "d2"}, {"id": "metodologia/fiszki:c7a3aea2", "q": "Jakie dwie cechy muszą mieć wartości zmiennej?", "a": "<p>Muszą być <b>wyczerpujące</b> (każda obserwacja ma swoją kategorię) i <b>wzajemnie rozłączne</b> (tylko jedną).</p>", "src": "Sprawdź się — wykład 2", "k": ["wyczerpujące", "wzajemnie rozłączne"], "u": "wyklad-2.html", "s": ""}, {"id": "metodologia/fiszki:61250655", "q": "Nie wiesz, jak szczegółowo pytać o wiek. Co robisz?", "a": "<p>Pytasz szczegółowo (dokładny wiek). Zawsze możesz zgrupować wartości później, ale nie odzyskasz szczegółów z przedziałów.</p>", "src": "Sprawdź się — wykład 2", "k": ["pytać szczegółowo", "grupować później", "szczegółów nie odzyskasz"], "u": "wyklad-2.html", "s": ""}, {"id": "metodologia/fiszki:063de4d6", "q": "Babbie, ćw. 3: określ poziom pomiaru — rasa, kolejność na mecie, liczba dzieci, ludność krajów, stosunek do energii jądrowej (bardzo przychylny … bardzo nieprzychylny), region pochodzenia, poglądy (bardzo liberalne … bardzo konserwatywne).", "a": "<p>Rasa — nominalna. Kolejność na mecie — porządkowa. Liczba dzieci — ilorazowa. Ludność krajów — ilorazowa. Stosunek do energii jądrowej — porządkowa. Region pochodzenia — nominalna. Poglądy polityczne — porządkowa.</p>", "src": "Sprawdź się — wykład 2", "k": ["rasa, region: nominalne", "kolejność na mecie, stosunek, poglądy: porządkowe", "liczba dzieci, ludność: ilorazowe"], "u": "wyklad-2.html", "s": ""}, {"id": "metodologia/fiszki:72627586", "q": "Dlaczego IQ jest na skali interwałowej, a nie ilorazowej?", "a": "<p>Ma równe odstępy, ale nie ma zera bezwzględnego: 0 w teście nie oznacza braku inteligencji. Dlatego nie wolno mówić, że IQ 150 to „1,5 raza” więcej inteligencji niż 100.</p>", "src": "Sprawdź się — wykład 2", "k": ["równe odstępy", "brak zera bezwzględnego", "nie wolno mówić „1,5 raza”"], "u": "wyklad-2.html", "s": "d4"}, {"id": "metodologia/fiszki:a3dde748", "q": "Zakodowałaś płeć jako 1 i 2. Średnia wyszła 1,4. Co to znaczy?", "a": "<p>Sama średnia nic nie znaczy — cyfry na skali nominalnej to nazwy kategorii. Sensowna informacja to liczebność lub procent (tu: 60% osób z kodem 1).</p>", "src": "Sprawdź się — wykład 2", "k": ["średnia nic nie znaczy", "cyfry to nazwy kategorii", "sens ma liczebność lub procent"], "u": "wyklad-2.html", "s": ""}, {"id": "metodologia/fiszki:c3aecd6a", "q": "Czy z odpowiedzi „młody / w średnim wieku / starszy” odtworzysz dokładny wiek?", "a": "<p>Nie. Przekształcać można tylko w dół (ilorazowa → porządkowa → nominalna), nigdy w górę.</p>", "src": "Sprawdź się — wykład 2", "k": ["nie", "przekształcać tylko w dół"], "u": "wyklad-2.html", "s": ""}, {"id": "metodologia/fiszki:e130d2ed", "q": "Czy pojedyncze pytanie w skali Likerta jest pomiarem ilościowym?", "a": "<p>Nie — jest porządkowe. Jako interwałową traktuje się dopiero sumę lub średnią z całej skali lub podskali.</p>", "src": "Sprawdź się — wykład 2", "k": ["nie, porządkowe", "interwałowa dopiero suma lub średnia skali"], "u": "wyklad-2.html", "s": "d5"}, {"id": "metodologia/fiszki:c0083014", "q": "Zmienna ciągła a dyskretna — przykład każdej.", "a": "<p>Ciągła: dowolne wartości, także ułamkowe (prędkość 959,5 km/h). Dyskretna: tylko całkowite (liczba dziur, liczba dzieci).</p>", "src": "Sprawdź się — wykład 2", "k": ["ciągła: dowolne wartości (prędkość)", "dyskretna: całkowite (liczba dzieci)"], "u": "wyklad-2.html", "s": "d4"}, {"id": "metodologia/fiszki:f65de9c8", "q": "Waga zawsze pokazuje o 3 kg za mało. Jest rzetelna? Trafna?", "a": "<p>Rzetelna (za każdym razem ten sam wynik), ale nietrafna / niepoprawna — systematyczny błąd (obciążenie). To lewa tarcza.</p>", "src": "Sprawdź się — wykład 2", "k": ["rzetelna", "nietrafna", "błąd systematyczny"], "u": "wyklad-2.html", "s": ""}, {"id": "metodologia/fiszki:b14741da", "q": "Wymień cztery metody sprawdzania rzetelności.", "a": "<p>Test powtórny, metoda połówkowa, użycie ustalonych mierników, kontrola rzetelności osób zatrudnionych (ankieterów, koderów).</p>", "src": "Sprawdź się — wykład 2", "k": ["test powtórny", "metoda połówkowa", "ustalone mierniki", "kontrola ankieterów i koderów"], "u": "wyklad-2.html", "s": "d7"}, {"id": "metodologia/fiszki:81cf7e84", "q": "Egzamin wstępny dobrze przewiduje średnią na studiach. Jaki to rodzaj trafności?", "a": "<p>Kryterialna (predykcyjna).</p>", "src": "Sprawdź się — wykład 2", "k": ["kryterialna (predykcyjna)"], "u": "wyklad-2.html", "s": ""}, {"id": "metodologia/fiszki:113c05c2", "q": "Test z matematyki sprawdza tylko dodawanie. Której trafności brakuje?", "a": "<p>Treściowej — nie obejmuje całego zakresu pojęcia.</p>", "src": "Sprawdź się — wykład 2", "k": ["treściowej", "nie obejmuje całego zakresu pojęcia"], "u": "wyklad-2.html", "s": "d7"}, {"id": "metodologia/fiszki:d10e116b", "q": "Miernik satysfakcji z małżeństwa nie wiąże się z wiernością, choć teoria tego wymaga. Co to podważa?", "a": "<p>Trafność teoretyczną.</p>", "src": "Sprawdź się — wykład 2", "k": ["trafność teoretyczną"], "u": "wyklad-2.html", "s": ""}, {"id": "metodologia/fiszki:05a73e69", "q": "Na czym polega napięcie między rzetelnością a trafnością?", "a": "<p>Rzetelne, proste mierniki (liczba skarg) często zubażają bogactwo znaczeń pojęcia, więc są mniej trafne. Bogatsze metody (obserwacja, rozmowy) są trafniejsze, ale mniej rzetelne. Rozwiązanie: mierzyć pojęcie na kilka sposobów.</p>", "src": "Sprawdź się — wykład 2", "k": ["proste mierniki rzetelne, ale ubogie", "bogate metody trafniejsze, mniej rzetelne", "mierzyć na kilka sposobów"], "u": "wyklad-2.html", "s": "d7"}, {"id": "metodologia/fiszki:59ea4916", "q": "Czym różni się hipoteza kierunkowa od bezkierunkowej? Która jest mocniejsza?", "a": "<p><strong>Bezkierunkowa</strong> nie wskazuje kierunku zależności (np. „koreluje”, „wpływa”). <strong>Kierunkowa</strong> wskazuje kierunek (np. „wyższy niż”, „negatywnie koreluje”) i jest <strong>metodologicznie mocniejsza</strong>.</p>", "src": "Wykład 2 — slajdy", "k": ["bezkierunkowa: bez kierunku", "kierunkowa: wskazuje kierunek", "kierunkowa mocniejsza"], "u": "wyklad-2.html", "s": "d9"}, {"id": "metodologia/fiszki:9678e4ba", "q": "Czy „u osób adoptowanych w dzieciństwie” jest zmienną w hipotezie?", "a": "<p><strong>Nie.</strong> To tylko określenie grupy badanej (stała), tak jak „pielęgniarki”. Zmienne to unikowy styl przywiązania i satysfakcja z relacji romantycznej w dorosłości.</p>", "src": "Wykład 2 — slajdy", "k": ["nie, to określenie grupy (stała)", "zmienne: styl przywiązania i satysfakcja"], "u": "wyklad-2.html", "s": "d9"}, {"id": "metodologia/fiszki:df3590ad", "q": "Czym są operacjonalizacja i wskaźniki?", "a": "<p><strong>Operacjonalizacja</strong>: sposób pomiaru, czyli uzyskania informacji o wartości zmiennej. <strong>Wskaźniki</strong>: informacje o wartości zmiennej uzyskane dzięki operacjonalizacji.</p>", "src": "Wykład 2 — slajdy", "k": ["operacjonalizacja: sposób pomiaru", "wskaźniki: uzyskane informacje o wartości"], "u": "wyklad-2.html", "s": "d10"}, {"id": "metodologia/fiszki:42d3e649", "q": "Wymień jakościowe i ilościowe metody pomiaru psychologicznego.", "a": "<p><strong>Jakościowe</strong>: wywiad, obserwacja, analiza wytworów. <strong>Ilościowe</strong>: testy psychologiczne (kwestionariusze, próby zadaniowe). Osobno: pomiar aparaturą (EEG, fMRI), często ilościowy.</p>", "src": "Wykład 2 — slajdy", "k": ["jakościowe: wywiad, obserwacja, wytwory", "ilościowe: testy", "aparatura (EEG, fMRI)"], "u": "wyklad-2.html", "s": "d10"}, {"id": "metodologia/fiszki:c4584cee", "q": "Jakie są rodzaje wywiadu ze względu na strukturę?", "a": "<p>Całkowicie ustrukturalizowany (może zawierać pomiar ilościowy), częściowo ustrukturalizowany i swobodny (z ukrytą strukturą).</p>", "src": "Wykład 2 — slajdy", "k": ["całkowicie ustrukturalizowany", "częściowo ustrukturalizowany", "swobodny"], "u": "wyklad-2.html", "s": "d10"}, {"id": "metodologia/fiszki:7bd414fb", "q": "Co wiadomo o trafności „znakowej” interpretacji rysunków (np. Machover)?", "a": "<p>Badania są w większości <strong>negatywne</strong>; nie potwierdziły się nawet popularne wskaźniki lęku (wielkość rysunku, siła kreski). Błędem jest przypisywanie znaczenia wskaźnikom bez empirycznej weryfikacji trafności.</p>", "src": "Wykład 2 — slajdy", "k": ["badania w większości negatywne", "wskaźniki lęku się nie potwierdziły", "potrzeba weryfikacji trafności"], "u": "wyklad-2.html", "s": "d11"}, {"id": "metodologia/fiszki:d3430aa7", "q": "Wymień pięć kryteriów dobroci testu psychologicznego.", "a": "<p>Standaryzacja, trafność, rzetelność, normalizacja, obiektywność.</p>", "src": "Wykład 2 — slajdy", "k": ["standaryzacja", "trafność", "rzetelność", "normalizacja", "obiektywność"], "u": "wyklad-2.html", "s": "d12"}, {"id": "metodologia/fiszki:c2dd6a18", "q": "Czym różni się trafność od rzetelności testu?", "a": "<p><strong>Trafność</strong>: czy test mierzy to, co ma mierzyć. <strong>Rzetelność</strong>: jak dokładnie to mierzy.</p>", "src": "Wykład 2 — slajdy", "k": ["trafność: czy mierzy to, co ma", "rzetelność: jak dokładnie"], "u": "wyklad-2.html", "s": "d12"}, {"id": "metodologia/fiszki:5181d8cf", "q": "Co mówi α Cronbacha i jaki jest próg akceptowalnej rzetelności?", "a": "<p>To wskaźnik spójności wewnętrznej: im bliżej 1, tym wyższa rzetelność. Próg akceptowalnej rzetelności to <strong>0,70</strong>.</p>", "src": "Wykład 2 — slajdy", "k": ["spójność wewnętrzna", "bliżej 1 = wyższa rzetelność", "próg 0,70"], "u": "wyklad-2.html", "s": "d12"}, {"id": "metodologia/fiszki:d69b9db8", "q": "Kiedy używa się wyników surowych, a kiedy znormalizowanych?", "a": "<p><strong>Surowe</strong>: w naukowych badaniach grupowych (są dokładniejsze). <strong>Znormalizowane</strong>: w badaniach indywidualnych, zwykle diagnostycznych, by określić poziom cechy na tle populacji.</p>", "src": "Wykład 2 — slajdy", "k": ["surowe: badania grupowe", "znormalizowane: diagnoza indywidualna"], "u": "wyklad-2.html", "s": "d12"}, {"id": "metodologia/fiszki:e8f05da3", "q": "Czym różni się podejście idiograficzne od nomotetycznego?", "a": "<p><strong>Idiograficzne</strong>: studium przypadku, dominują metody jakościowe, wnioski tylko o badanej osobie. <strong>Nomotetyczne</strong>: badanie próby, dominują metody ilościowe, wnioski o populacji (gdy próba jest reprezentatywna).</p>", "src": "Wykład 2 — slajdy", "k": ["idiograficzne: studium przypadku, jakościowe", "nomotetyczne: próba, ilościowe", "wnioski o populacji"], "u": "wyklad-2.html", "s": "d12"}];
